package net.civeira.phylax.integrationtest.features.oauth.scenario;

import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;

import io.quarkus.arc.profile.IfBuildProfile;
import jakarta.annotation.Priority;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Alternative;
import net.civeira.phylax.features.oauth.consent.domain.GdprConsentPurposeItem;
import net.civeira.phylax.features.oauth.consent.domain.gateway.GdprConsentGateway;

@IfBuildProfile("test")
@Alternative
@Priority(1)
@ApplicationScoped
public class ScenarioGdprConsentGateway implements GdprConsentGateway {

  private Supplier<List<GdprConsentPurposeItem>> purposesSupplier = List::of;
  private final AtomicInteger decisionsCount = new AtomicInteger();
  private Map<String, Boolean> lastDecisions;

  public void whenPurposes(Supplier<List<GdprConsentPurposeItem>> behavior) {
    this.purposesSupplier = behavior;
  }

  public void reset() {
    purposesSupplier = List::of;
    decisionsCount.set(0);
    lastDecisions = null;
  }

  public int getDecisionsCount() {
    return decisionsCount.get();
  }

  public Map<String, Boolean> getLastDecisions() {
    return lastDecisions;
  }

  @Override
  public List<GdprConsentPurposeItem> pendingPurposes(String tenant, String username) {
    return purposesSupplier.get();
  }

  @Override
  public void storePurposeDecisions(String tenant, String username,
      Map<String, Boolean> decisionsByPurposeUid, String ipAddress, String userAgent) {
    decisionsCount.incrementAndGet();
    lastDecisions = decisionsByPurposeUid;
  }
}
